package api

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"net/http"
	"strings"
	"sync/atomic"
	"time"
)

// requestIDWriter carries the request identifier through nested handlers. It
// intentionally does not trust an incoming request header: identifiers are
// generated by the Server and are safe to put in operator-facing support
// messages and logs.
type requestIDWriter struct {
	http.ResponseWriter
	id string
}

func (w *requestIDWriter) RequestID() string           { return w.id }
func (w *requestIDWriter) Unwrap() http.ResponseWriter { return w.ResponseWriter }

var requestIDFallback atomic.Uint64

func newRequestID() string {
	var raw [16]byte
	if _, err := rand.Read(raw[:]); err == nil {
		return hex.EncodeToString(raw[:])
	}
	// crypto/rand should be available on supported platforms. Keep the error
	// path observable without turning an otherwise safe error response into a
	// panic or a missing request identifier.
	n := requestIDFallback.Add(1)
	return fmt.Sprintf("fallback-%x-%x", time.Now().UnixNano(), n)
}

func responseRequestID(w http.ResponseWriter) string {
	if provider, ok := w.(interface{ RequestID() string }); ok {
		if id := strings.TrimSpace(provider.RequestID()); id != "" {
			w.Header().Set("X-Request-ID", id)
			return id
		}
	}
	if id := strings.TrimSpace(w.Header().Get("X-Request-ID")); id != "" {
		return id
	}
	id := newRequestID()
	w.Header().Set("X-Request-ID", id)
	return id
}

// withRequestID gives every control-plane response one stable identifier,
// including responses produced by a nested fallback or node middleware.
func withRequestID(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		id := responseRequestID(w)
		wrapped := &requestIDWriter{ResponseWriter: w, id: id}
		wrapped.Header().Set("X-Request-ID", id)
		next.ServeHTTP(wrapped, r)
	})
}

func errorHint(code string) string {
	switch code {
	case "unauthorized", "invalid_credentials", "node_auth_required":
		return "请重新登录或检查节点凭据"
	case "forbidden", "admin_required", "request_header_required":
		return "请确认当前账号权限和请求来源"
	case "not_found", "task_not_found", "node_not_registered":
		return "请刷新页面并确认资源仍然存在"
	case "invalid_json", "extra_json", "json_required":
		return "请按接口要求提交一个 JSON 对象"
	case "db_error", "database_error", "node_registry_unavailable":
		return "请查看 Server 日志中的请求编号后重试"
	case "node_revoked":
		return "请在节点清册中恢复或重新登记节点"
	case "task_not_terminal", "task_has_findings", "task_state_conflict":
		return "请刷新任务状态后选择当前允许的操作"
	case "backend_capability_unavailable":
		return "请切换到已启用该能力的存储后端"
	default:
		return "请检查请求参数后重试"
	}
}

func normalizeAPIError(w http.ResponseWriter, value APIError) APIError {
	value.Code = strings.TrimSpace(value.Code)
	if value.Code == "" {
		value.Code = strings.TrimSpace(value.Error)
	}
	if value.Code == "" {
		value.Code = "internal_error"
	}
	// Keep the former field during the migration so older workers and browser
	// bundles can still select their localized message.
	value.Error = value.Code
	if strings.TrimSpace(value.Message) == "" {
		value.Message = value.Code
	}
	if strings.TrimSpace(value.Hint) == "" {
		value.Hint = errorHint(value.Code)
	}
	value.RequestID = responseRequestID(w)
	return value
}
